"""Actual six original IDH-series assets personally inspected, thirteen scopes."""
import json
from pathlib import Path
r=Path('benchmarks/dense500');n='PMC12880940.1';s=json.load(open(r/'sources'/f'{n}.json'));seg={x['segment_id']:x['text'] for x in s['segments']};assets=json.load(open(r/'figure-assets'/f'{n}.json'))
def ev(sid,q):assert q in seg[sid];return {'segment_id':sid,'quote':q}
def tag(value,basis,cue=None,evidence=None,raw=None):return dict(value=value,as_documented=raw,basis=basis,visual_cue=cue,evidence=evidence or [],certainty='clear')
def sig(text,role,sid,quote):return dict(statement=text,role=role,clinical_fact_status='unreviewed_annotation',basis='caption',visual_cue=None,evidence=[ev(sid,quote)],certainty='clear')
desc={
1:[(None,'Twelve-lead ECG on pale squared paper.','Black waveform traces occupy two main columns: limb leads I,II,III,aVR,aVL,aVF at left, chest leads V1–V6 at right, with a lower continuous strip. Narrow vertical complexes recur across the grid; chest-lead baseline and terminal-wave shapes differ by row. Calibration pulses and header text are visible. The printed25mm/s and10mm/mV calibrations are readable; other small header acquisition/patient text is not reliably transcribed.')],
2:[('A','Grayscale apical cardiac ultrasound sector with chamber labels and white arrows.','A triangular gray speckled sector is displayed on black. Dark chambers are labelled RA,RV,LA and LV; a smaller dark pocket near the upper apex is labelled IDH. Multiple white arrows point toward its boundaries; an oval A label sits at lower right.'),('B','Color-flow cardiac ultrasound view with arrows.','Gray sector image contains a rectangular color box. Blue pixels lie above and left of a red/orange column near the labelled LV. White arrows converge around the central colored boundary and upper dark pocket; oval B label is at lower right. Color represents displayed Doppler overlay; direction/velocity is not inferred from red/blue alone.'),('C','Grayscale ultrasound image with IDH label and triangular marker.','A dark upper pocket labelled IDH is bordered by gray tissue. A yellow triangle outlined in blue sits along its left side. White chamber walls lead downward into a larger dark chamber; oval C label is at lower right. No readable numeric lesion dimension is printed.')],
3:[('A','Follow-up grayscale cardiac ultrasound image with IDH label and arrows.','A dark pocket in the upper central sector is labelled IDH; three white arrows point toward its upper and lower margins. Speckled gray tissue surrounds it, with a larger dark chamber below. A gray display bar is present along the right border; oval A label lies at lower right.'),('B','Follow-up color-flow ultrasound image.','A gray ultrasound sector contains a broad red/orange region in the lower central chamber and blue patches near the upper dark pocket. Several white arrows indicate tissue/color boundaries. Oval B label is at lower right. The actual displayed geometry is described without measuring growth from differing fields of view.'),('C','Follow-up grayscale apical view with IDH label and triangle.','A relatively rounded dark upper pocket carries the IDH label, with white arrows near its upper rim. A yellow triangle with blue outline marks the lower left edge. Gray speckled tissue and chamber walls occupy the remaining sector; oval C label is at lower right.')],
4:[(None,'Follow-up ECG showing closely spaced complexes.','Two columns of lead-labelled black traces appear on pale square-grid paper, limb leads at left and V1–V6 at right, with a continuous lower strip. Repeated complexes are closely spaced, especially in upper limb-lead rows; precordial waveforms have broad elevated portions and varied terminal shapes. Calibration pulses,25mm/s,10mm/mV and a printed189bpm header are visible. Other faint acquisition text is not used as patient chronology.')],
5:[('A','Cardiac ultrasound sector with red/blue color overlay and white arrows.','Dark elongated chamber labelled LV lies centrally in a narrow gray ultrasound sector. A rectangular box displays red and blue pixels. White arrows point to the colored interface and adjacent region labelled IDH. Oval A appears at lower right; small depth numbers are visible but their unit and exact boundaries are not reliably legible.'),('B','Grayscale ultrasound sector with star, triangle and arrow.','A yellow five-point star marks an upper dark region; a yellow triangle with blue border lies below it. A white arrow points to a gray boundary above and left of these symbols. Gray speckled myocardium surrounds dark spaces. Oval B appears at lower right.'),('C','Rendered cardiac volume with orange tissue and blue outer surface.','A roughly rectangular blue-toned volume frame surrounds orange/brown rendered tissue and dark internal cavities. A white arrow points at the upper right tissue edge; oval C label appears at lower right. This is a static rendered volume, not motion evidence.'),('D','Oblique rendered volume with orange/brown tissue and dark cavity.','An elongated oblique orange/brown tissue volume lies against black; a dark internal opening is visible in its upper half, with a small red mark nearby. Gray/blue surface occupies part of the right edge. Oval D label appears at lower right.')],
6:[(None,'Second patient twelve-lead ECG.','Two columns of black waveform traces run across pale grid paper, limb leads at left and precordial leads V1–V6 at right, with a long lower rhythm strip. Upward complexes and sloping or depressed terminal portions vary between leads. Calibration pulses and10mm/mV and25mm/s text are visible. Small filter/header text is not interpreted as a clinical measurement or date.')]
}
out=[]
for num,manifest in enumerate(assets['figures'],1):
 sid=f'b{12+num:05d}';caption=seg[sid];pid='p1' if num<=4 else 'p2';panels=[];assignments=[]
 for letter,general,detail in desc[num]:
  wave=num in (1,4,6);charts=[];mods=[];subs=[];limits=[]
  if wave:
   readings=[]
   for metric,val,unit,raw in [('ECG paper speed',25,'mm/s','25 mm/s'),('ECG gain',10,'mm/mV','10 mm/mV')]+([('Printed header heart rate',189,'bpm','189 bpm')] if num==4 else []):
    readings.append(dict(metric_name=metric,metric_kind='heart_rate' if 'heart rate' in metric else 'ecg',series_label='ECG',time_or_x_label=None,value_text=raw,numeric_value=val,unit=unit,precision='printed_exact',basis='pixels',visual_cue='Printed header calibration/rate '+raw,evidence=[],certainty='clear'))
   charts=[dict(chart_type='waveform',title=None,scope='individual',is_clinical_chart=True,x_axis=dict(label=None,unit=None,scale='unknown',visible_ticks=[]),y_axis=dict(label=None,unit=None,scale='unknown',visible_ticks=[]),measured_quantities=[tag('electrocardiographic waveform','caption',evidence=[ev(sid,caption)],raw='electrocardiogram')],readings=readings,limitations=['Grid calibrations are recorded, but waveform voltage/duration/heart rate is not estimated from grid spacing. Faint header dates and other patient/acquisition text are not used to anchor clinical events.'])]
   sigs=[sig(caption.split('\n',1)[1],'diagnostic_evidence',sid,caption)]
   limits=['Caption rhythm/ST/T interpretations are author claims, not a new pixel-only ECG diagnosis.']
  else:
   mods=[tag('ultrasound','caption',evidence=[ev(sid,caption)],raw='Echocardiogram' if num in [2,5] else 'echocardiogram')]
   if letter=='B' and num in [2,3] or num==5 and letter=='A':subs=[tag('color Doppler overlay','pixels',cue='Red and blue image pixels confined to an ultrasound color box')]
   elif num==5 and letter in ['C','D']:subs=[tag('three-dimensional echocardiographic rendering','caption',evidence=[ev(sid,caption)],raw='Three-dimensional imaging')]
   else:subs=[tag('grayscale cardiac ultrasound','pixels',cue='Gray speckled sector image on black background')]
   sigs=[sig('Authors describe '+('initial apical hematoma/ventricular aneurysm-thrombosis' if num==2 else 'follow-up hematoma expansion and apical pseudoaneurysm/thrombosis, with the body retaining diagnostic uncertainty' if num==3 else 'Case2 epicardial integrity, hematomas and pericardial effusion; narrative and caption sites differ.'),'disease_course' if num==3 else 'diagnostic_evidence',sid,caption)]
   limits=['No EF, lesion dimensions, imaging approach (TTE versus TEE), motion, velocity or chamber flow direction is inferred from this static image.']
   if num==3:limits.append('Apparent pocket size differs between images, but pixel dimensions are not calibrated comparable clinical growth measurements; expansion is an author caption claim.')
   if num==5:limits.append('Body describes inferior posterior basal LV wall and calls this Fig6, while actual Fig5/caption describes apical/lateral images. Both source versions are preserved without resolving site or figure-callout conflict.')
  panels.append(dict(panel=letter,general_description=general,detailed_description=detail,image_kind='graph' if wave else 'medical_imaging',has_chart=wave,charts=charts,imaging_modalities=mods,imaging_submodalities=subs,medical_domains=[tag('cardiology','caption',evidence=[ev(sid,caption)])],body_parts=[tag('heart','caption',evidence=[ev(sid,caption)],raw='heart' if 'heart' in caption else None)],mentioned_categories=[],pixel_observations=[detail],caption_claims=[tag(caption.split('\n',1)[1],'caption',evidence=[ev(sid,caption)],raw=caption.split('\n',1)[1])],clinical_significance=sigs,diagram_relations=[],limitations=limits))
  assignments.append(dict(panel=letter,patient_ids=[pid],scope='individual',subject='patient',evidence=[ev(sid,caption),ev('b00004' if pid=='p1' else 'b00005','A 73-year-old woman' if pid=='p1' else 'A 69-year-old woman')],rationale='Explicit caption '+('first case/Case1' if pid=='p1' else 'second case/Case2')+' establishes ownership. ECG or in-vivo echocardiography concerns the patient; no specimen. For Figures5/6 ownership and modality follow captions and actual assets despite reversed body callouts.'))
 overall=['Actual source asset viewed; no claim of independent diagnostic validation.','Some tiny machine/depth/header text is not reliably readable; no undocumented unit, sampling time or test approach inferred.']
 if num in [5,6]:overall.append('Body callouts Fig5ECG and Fig6echo are reversed relative to actual images and caption labels; preserved as source inconsistency.')
 visual=dict(figure_id=manifest['figure_id'],general_description='; '.join(p['general_description'] for p in panels),detailed_description=('One whole ECG strip.' if num in [1,4,6] else str(len(panels))+' side-by-side lettered cardiac ultrasound panels.')+' '+ ' '.join((p['panel']+': ' if p['panel'] else '')+p['detailed_description'] for p in panels),panels=panels,limitations=overall)
 attribution=dict(figure_id=manifest['figure_id'],assignments=assignments,limitations=['Figure5/6 body callout reversal does not change explicit caption case ownership.'] if num in [5,6] else [])
 out.append(dict(figure_id=manifest['figure_id'],status='inspected',assets=[{'url':z['url'],'sha256':z['sha256']} for z in manifest['assets']],analysis=dict(visual=visual,attribution=attribution),limitations=overall))
(r/'visual-submissions'/f'{n}.json').write_text(json.dumps(dict(format='dense-figure-reference/1',article_id=n,source_text_sha256=s['text_sha256'],figures=out),ensure_ascii=False,indent=2)+'\n')
print('figures',len(out),'scopes',sum(len(x['analysis']['visual']['panels']) for x in out))
